const data = $json;

const requiredFields = [
  "Customer Name",
  "Customer Email",
  "Customer ID",
  "Subscription Plan",
  "Payment Amount",
  "Payment Date",
  "Failure Reason",
  "Retry Count"
];

const missingFields = requiredFields.filter(
  field =>
    data[field] === undefined ||
    data[field] === null ||
    data[field] === ""
);

const amountValid = Number(data["Payment Amount"]) > 0;
const retryValid = Number(data["Retry Count"]) >= 0;

return {
  json: {
    ...data,
    data_valid:
      missingFields.length === 0 &&
      amountValid &&
      retryValid,
    missing_fields: missingFields
  }
};

